  // Верните { ctr, cvr, overall } — проценты с одним знаком после запятой.
  // Нулевой знаменатель -> null для этой доли.
  // Некорректный ввод (отрицательное, не число) -> null целиком.
  // Return { ctr, cvr, overall } — percentages with one decimal.
  // A zero denominator -> null for that rate.
  // Invalid input (negative, not a number) -> null outright.
}

practice.solution:
function funnelRates(impressions, visits, signups) {
  const inputs = [impressions, visits, signups];
  if (!inputs.every(n => typeof n === 'number' && Number.isFinite(n) && n >= 0)) return null;
  const rate = (num, den) => den > 0 ? Math.round(num / den * 1000) / 10 : null;
  return { ctr: rate(visits, impressions), cvr: rate(signups, visits), overall: rate(signups, impressions) };
}

