function buildUtm(base, source, medium, campaign) {
  // Верните строку: base + ?utm_source=...&utm_medium=...&utm_campaign=...
  // Нормализация: trim, нижний регистр, пробелы -> дефисы, encodeURIComponent для кириллицы.
  // Пустые значения пропускаются; если все пустые — base без параметров.
  // Нестроковый или пустой base -> null.
  // Return a string: base + ?utm_source=...&utm_medium=...&utm_campaign=...
  // Normalization: trim, lowercase, spaces -> hyphens, encodeURIComponent for Cyrillic.
  // Empty values are skipped; if all are empty — base without parameters.
  // A non-string base -> null.
}

practice.solution:
function buildUtm(base, source, medium, campaign) {
  if (typeof base !== 'string' || base.length === 0) return null;
  const norm = v => String(v ?? '').trim().toLowerCase().replace(/\s+/g, '-');
  const pairs = [['utm_source', norm(source)], ['utm_medium', norm(medium)], ['utm_campaign', norm(campaign)]]
    .filter(([, v]) => v.length > 0)
    .map(([k, v]) => k + '=' + encodeURIComponent(v));
  return pairs.length === 0 ? base : base + '?' + pairs.join('&');
}

