function kpiCompletion(plan, actual) {
  // Верните процент выполнения (факт/план*100) с одним знаком после запятой.
  // План <= 0 -> null (при любом факте). Отрицательный факт -> null.
  // Return the completion percent (actual/plan*100) with one decimal.
  // Plan <= 0 -> null (regardless of the actual). A negative actual -> null.
}

practice.solution:
function kpiCompletion(plan, actual) {
  if (typeof plan !== 'number' || typeof actual !== 'number' || !Number.isFinite(plan) || !Number.isFinite(actual)) return null;
  if (plan <= 0 || actual < 0) return null;
  return Math.round(actual / plan * 1000) / 10;
}

