function campaignCosts(spend, impressions, clicks, conversions, revenue) {
  // Верните { cpc, cpm, cpa, roas } с одним знаком после запятой.
  // cpc = spend/clicks; cpm = spend/impressions*1000; cpa = spend/conversions; roas = revenue/spend.
  // Нулевой знаменатель -> null для этой метрики (кроме roas: spend > 0 обязателен).
  // Некорректный ввод -> null целиком.
  // Return { cpc, cpm, cpa, roas } with one decimal.
  // A zero denominator -> null for that metric (except roas: spend > 0 required).
  // Invalid input -> null outright.
}

practice.solution:
function campaignCosts(spend, impressions, clicks, conversions, revenue) {
  const inputs = [spend, impressions, clicks, conversions, revenue];
  if (!inputs.every(n => typeof n === 'number' && Number.isFinite(n) && n >= 0)) return null;
  const rate = (num, den, scale = 1) => den > 0 ? Math.round(num / den * scale * 10) / 10 : null;
  if (!(spend > 0)) return null;
  return {
    cpc: rate(spend, clicks),
    cpm: rate(spend, impressions, 1000),
    cpa: rate(spend, conversions),
    roas: Math.round(revenue / spend * 10) / 10
  };
}

