function abCompare(impressionsA, visitsA, impressionsB, visitsB) {
  // Верните { gapPoints, liftPercent } с одним знаком после запятой.
  // gapPoints = ctrB - ctrA (в процентных пунктах); liftPercent = gap / ctrA * 100.
  // Нулевые показы любой группы -> null. Нулевой ctrA -> liftPercent null, gapPoints считается.
  // Некорректный ввод -> null целиком.
  // Return { gapPoints, liftPercent } with one decimal.
  // gapPoints = ctrB - ctrA (percentage points); liftPercent = gap / ctrA * 100.
  // Zero impressions in either group -> null. Zero ctrA -> liftPercent null, gapPoints still computes.
  // Invalid input -> null outright.
}

practice.solution:
function abCompare(impressionsA, visitsA, impressionsB, visitsB) {
  const inputs = [impressionsA, visitsA, impressionsB, visitsB];
  if (!inputs.every(n => typeof n === 'number' && Number.isFinite(n) && n >= 0)) return null;
  const ctr = (visits, impressions) => impressions > 0 ? visits / impressions * 100 : null;
  const ctrA = ctr(visitsA, impressionsA), ctrB = ctr(visitsB, impressionsB);
  if (ctrA === null || ctrB === null) return null;
  const gap = Math.round((ctrB - ctrA) * 10) / 10;
  const lift = ctrA > 0 ? Math.round((ctrB - ctrA) / ctrA * 1000) / 10 : null;
  return { gapPoints: gap, liftPercent: lift };
}

